import { ConfidentialClientApplication } from "@azure/msal-node";

const client = new ConfidentialClientApplication({
  clientId: process.env.CLIENT_ID!,
  authority: `https://login.microsoftonline.com/${process.env.TENANT_ID}`,
  clientSecret: process.env.CLIENT_SECRET, // omit for public clients using PKCE
});

// 1. Redirect the user here
const authUrl = await client.getAuthCodeUrl({
  scopes: ["openid", "profile", "offline_access", "api://my-api/Orders.Read"],
  redirectUri: "https://app.example.com/auth/callback",
  prompt: "select_account",
});

// 2. Exchange the ?code= value from the callback for tokens
const result = await client.acquireTokenByCode({
  code: req.query.code as string,
  scopes: ["openid", "profile", "offline_access", "api://my-api/Orders.Read"],
  redirectUri: "https://app.example.com/auth/callback",
});

console.log(result.accessToken, result.idToken);
